    if n == 0:
        return 0
    contrib = []
    for i in range(n):
        x = values[i]
        p = x*x*x
        if i > 0:
            p = p + x * values[i-1]
        contrib.append(p)
    for _ in range(3):
        acc = 0
        new = []
        for v in contrib:
            acc = acc + v
            new.append(acc)
        contrib = new
    return contrib[-1]

